input.command:
$env:WIKI_MASTER_VAULT=(pwd).Path; $P='<CANDIDATE>/scripts'
$t = node "$P/op-begin.mjs" --op discover; $t; 
foreach($u in 'protocol','thin','failed'){ node "$P/clip.mjs" "http://127.0.0.1:57281/$u" --quality=medium --topic="Harbor delivery" --since $t; "exit $LASTEXITCODE" }
$t | Out-File $env:TEMP\harbor-token.txt

